section(__T["ESP"], function()
    local Tab = Window:AddTab(__T["ESP"], "eye")
    local EB = Tab:AddLeftGroupbox(__T["ESP"], "scan-eye")
    EB:AddToggle("esp_anom", { Text = __T["Anomaly ESP"], Default = true, Tooltip = __T["Fakes, infected, stains, fever"] })
    EB:AddToggle("esp_needs", { Text = __T["Baby Needs"], Default = false })
    EB:AddToggle("esp_thing", { Text = __T["Something ESP"], Default = true })
    local EP = {}
    local holder = Instance.new("Folder")
    holder.Name = "CW_" .. tostring(math.random(1e6))
    pcall(function() holder.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
    if not holder.Parent then holder.Parent = lp:WaitForChild("PlayerGui") end
    onClean(function() pcall(function() holder:Destroy() end) end)
    local function tag(m, text, col)
        local e = EP[m]
        if not e then
            local part = m:FindFirstChild("Head", true) or m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart", true)
            if not part then return end
            local bb = Instance.new("BillboardGui")
            bb.Adornee, bb.AlwaysOnTop, bb.Size, bb.StudsOffsetWorldSpace, bb.MaxDistance = part, true, UDim2.fromOffset(160, 40), Vector3.new(0, 2.2, 0), 400
            local tl = Instance.new("TextLabel")
            tl.BackgroundTransparency, tl.Size, tl.Font, tl.TextSize, tl.TextStrokeTransparency = 1, UDim2.fromScale(1, 1), Enum.Font.GothamBold, 13, 0.4
            tl.Parent = bb
            local hl = Instance.new("Highlight")
            hl.Adornee, hl.FillTransparency, hl.OutlineTransparency, hl.DepthMode = m, 0.75, 0.1, Enum.HighlightDepthMode.AlwaysOnTop
            bb.Parent, hl.Parent = holder, holder
            e = { bb = bb, tl = tl, hl = hl }
            EP[m] = e
        end
        e.tl.Text, e.tl.TextColor3, e.hl.FillColor, e.hl.OutlineColor = text, col, col, col
        e.seen = true
    end
    local RED, ORG, PUR, BLK, GRN, WHT = Color3.fromRGB(255, 60, 60), Color3.fromRGB(255, 160, 40), Color3.fromRGB(190, 120, 255), Color3.fromRGB(140, 140, 150), Color3.fromRGB(90, 230, 120), Color3.fromRGB(235, 235, 235)
    local function needs(b)
        local t = {}
        if b:GetAttribute("NeedFood") then t[#t + 1] = "Hungry" end
        if b:GetAttribute("NeedDiaper") then t[#t + 1] = "Diaper" end
        if b:GetAttribute("NeedPlay") then t[#t + 1] = "Play" end
        if b:GetAttribute("State") == "Runaway" then t[#t + 1] = "Leaving!" end
        local n = b:GetAttribute("Neglect")
        if n then t[#t + 1] = math.floor(n * 100) .. "%" end
        return table.concat(t, " · ")
    end
    task.spawn(function()
        while RUNNING do
            for _, e in pairs(EP) do e.seen = false end
            if IN_HOUSE then
                local f = Workspace:FindFirstChild("Babies")
                for _, b in ipairs(f and f:GetChildren() or {}) do
                    if b:IsA("Model") and not b:GetAttribute("PorchClone") and b:GetAttribute("State") ~= "Lost" then
                        local nm = tostring(b:GetAttribute("BabyName") or "")
                        if on("esp_anom") and (b:GetAttribute("Fake") or b:GetAttribute("Mimic") or b:GetAttribute("Suspect")) then tag(b, "FAKE", RED)
                        elseif on("esp_anom") and b:GetAttribute("Haunted") then tag(b, nm .. " · INFECTED", PUR)
                        elseif on("esp_anom") and b:GetAttribute("Stain") ~= nil then tag(b, nm .. " · STAIN", BLK)
                        elseif on("esp_anom") and b:GetAttribute("Sick") == "sick" then tag(b, nm .. " · FEVER", ORG)
                        elseif on("esp_anom") and b:GetAttribute("StolenUntil") then tag(b, nm .. " · STOLEN", ORG)
                        elseif on("esp_needs") then local n = needs(b) tag(b, nm .. (n ~= "" and ("\n" .. n) or ""), n ~= "" and WHT or GRN) end
                    end
                end
                for _, c in ipairs(Workspace:GetChildren()) do
                    if c:IsA("Model") then
                        if on("esp_anom") and (c:GetAttribute("Stranger") or c:GetAttribute("Suspect")) then tag(c, "STRANGER", RED)
                        elseif on("esp_thing") and c.Name == "Something" then local r = M.root() tag(c, "SOMETHING" .. (r and (" " .. math.floor((c:GetPivot().Position - r.Position).Magnitude) .. "m") or ""), RED) end
                    end
                end
                local mm = Workspace:FindFirstChild("Mimics")
                for _, c in ipairs(mm and mm:GetChildren() or {}) do if c:IsA("Model") and on("esp_anom") then tag(c, "MIMIC", RED) end end
            end
            for m, e in pairs(EP) do if not e.seen or not m.Parent then pcall(function() e.bb:Destroy() e.hl:Destroy() end) EP[m] = nil end end
            task.wait(0.25)
        end
    end)
end)
